}
const number = (n: number) => Math.round(n).toLocaleString('ru-RU');
const metrics = [
  {id: 'revenue', label: 'Выручка', icon: 'wallet', unit: '₽', title: 'Динамика выручки'},
  {id: 'orders', label: 'Заказы', icon: 'bag', unit: '', title: 'Динамика заказов'},
  {id: 'average', label: 'Средний чек', icon: 'layers', unit: '₽', title: 'Динамика среднего чека'},
  {id: 'conversion', label: 'Конверсия', icon: 'target', unit: '%', title: 'Динамика конверсии'},
] as const;
type Metric = typeof metrics[number]['id'];
type Datum = {date: Date; revenue: number; orders: number; average: number; conversion: number};
const dateLabel = (date: Date) => date.toLocaleDateString('ru-RU', {day: 'numeric', month: 'short'}).replace('.', '');
function makeData(days: number, project: string): Datum[] {
  const base = Array.from({length: days}, (_, i) => 25000 + i * 730 + Math.sin(i * 1.43) * 8900 + Math.cos(i * .57) * 5200);
  const scale = (1284560 * days / 30) / base.reduce((a, b) => a + b, 0) * (project === 'store' ? 1 : .72);
  return base.map((value, i) => {
    const date = new Date(2026, 8, 30 - days + i + 1);
    const revenue = Math.round(value * scale);
    const orders = Math.round(revenue / (697 + Math.sin(i) * 65));
