function aggregate(data: Datum[], group: string): Datum[] {
  const step = group === 'week' ? 7 : group === 'month' ? 30 : 1;
  return Array.from({length: Math.ceil(data.length / step)}, (_, i) => {
    const chunk = data.slice(i * step, (i + 1) * step);
    const revenue = chunk.reduce((sum, d) => sum + d.revenue, 0);
    const orders = chunk.reduce((sum, d) => sum + d.orders, 0);
