      {[0, 1, 2, 3, 4].map(i => <g key={i}><line x1="66" x2="1050" y1={y(max * i / 4)} y2={y(max * i / 4)} className="chart-grid"/><text x="49" y={y(max * i / 4) + 4} textAnchor="end" className="axis-text">{metric === '"'conversion' ? max * i / 4 : number(max * i / 4)}</text></g>)}
