await page.getByRole('button',{name:'Тёмная тема',exact:true}).click();
await page.screenshot({path:'/tmp/pulse-dark.png',fullPage:true});
if(await page.locator('.app').getAttribute('data-theme')"'!=='"'dark')throw Error('Theme did not change');
await page.reload();if(await page.locator('.app').getAttribute('data-theme')"'!=='"'dark')throw Error('Theme was not saved');
await page.getByRole('button',{name:'Светлая тема',exact:true}).click();
await page.locator('.metric-card').nth(1).click();if(await page.locator('h2').innerText()"'!=='"'Динамика заказовi')throw Error('Metric not changed');
await page.getByRole('radio',{name:'Неделя',exact:true}).check();
console.log('weekly points',await page.locator('.line-chart rect').count());
await page.getByRole('radio',{name:'Месяц',exact:true}).check();console.log('monthly points',await page.locator('.line-chart rect').count());
