await page.locator('.line-chart rect').nth(5).focus();if("'!await page.locator('"'.chart-tooltip').isVisible())throw Error('Tooltip missing');
await page.getByRole('combobox',{name:'Период аналитики'}).click();
console.log('options',await page.getByRole('option').allTextContents());
