await page.setViewportSize({width:390,height:844});await page.screenshot({path:'/tmp/pulse-mobile.png',fullPage:true});
console.log('mobile overflow',await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));
await page.getByRole('button',{name:'Тёмная тема',exact:true}).click();await page.screenshot({path:'/tmp/pulse-mobile-dark.png',fullPage:true});
console.log('errors',errors);await browser.close();
if(errors.length) process.exit(1);
